/**
 * Jinx Cannibal + Juggler: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Cannibal
 * Wiki: https://wiki.bloodontheclocktower.com/Juggler
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Each test quotes the wiki text it encodes word
 * for word in a `// Wiki: "..."` comment (CLAUDE.md, Trevor 2026-11-01 and 2026-11-02).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong, type Script } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { scenario, type Scenario } from '#lib/core/testing/scenario.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { nightStepAlerts } from '#lib/core/rules/night-alerts.ts';
import { withNightInfo } from '#lib/core/rules/night-info.ts';

const scriptOf = (ids: string[]): Script => ({
	meta: { name: 'Jinxed' },
	entries: ids.map((id) => ({ kind: 'official' as const, id }))
});
const script = scriptOf(['cannibal', 'juggler', 'imp', 'chef', 'empath', 'monk']);

/** The Cannibal's step for the gained Juggler ability tonight. */
const gainedStep = (s: Scenario) =>
	withNightInfo([], s.game, s.characters, 'other').find((step) => step.gained);
const learns = (s: Scenario) =>
	nightStepAlerts(s.game, 'cannibal', s.characters).filter((a) => a.kind === 'learns-gained');

describe('Cannibal + Juggler jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'cannibal', 'juggler');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('cannibal')?.name).toBe('Cannibal');
		expect(data.byId.get('juggler')?.name).toBe('Juggler');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['cannibal', 'juggler'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['cannibal'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['juggler'])).not.toContain(jinx);
	});

	describe("the living Cannibal learns the executed Juggler's number", () => {
		// The Juggler's first day: two guesses, one of them right, then the Juggler is executed
		// and the Cannibal eats them.
		const guessed = scenario(['cannibal', 'juggler', 'imp', 'chef', 'empath'], { script }).do(
			(s) => ({
				type: 'DayNote',
				characterId: 'juggler',
				seatId: s.seat('juggler'),
				text: '',
				guesses: [
					{ seatId: s.seat('chef'), characterId: 'chef' },
					{ seatId: s.seat('empath'), characterId: 'monk' }
				]
			})
		);
		const eaten = guessed.execute('juggler').reminder('juggler', 'cannibal', 'Lunch');

		it("is data in the Cannibal's rules", () => {
			expect(jinxRulesBetween('cannibal', 'juggler')).toEqual({ learns: { what: 'answer' } });
		});

		it("tonight the Cannibal's Juggler step answers with the Juggler's own guesses", () => {
			// Wiki: "If the Juggler guesses on their first day and dies by execution, tonight the
			// living Cannibal learns how many guesses the Juggler got correct."
			const step = gainedStep(eaten);
			expect(step?.gained).toMatchObject({ characterId: 'juggler', learns: 'answer' });
			expect(step?.info).toMatchObject({
				kind: 'answer',
				answers: [{ seatId: eaten.seat('cannibal'), kind: 'number', value: 1 }]
			});
			expect(learns(eaten)).toMatchObject([{ seatId: eaten.seat('cannibal'), learns: 'answer' }]);
		});

		it('the Correct reminders placed for the Juggler count as they would for the Juggler', () => {
			// Wiki: "If the Juggler guesses on their first day and dies by execution, tonight the
			// living Cannibal learns how many guesses the Juggler got correct."
			const marked = eaten
				.reminder('chef', 'juggler', 'Correct')
				.reminder('juggler', 'juggler', 'Correct');
			expect(gainedStep(marked)?.info).toMatchObject({
				answers: [{ kind: 'number', value: 2 }]
			});
		});

		it('a dead Cannibal learns nothing', () => {
			// Wiki: "If the Juggler guesses on their first day and dies by execution, tonight the
			// living Cannibal learns how many guesses the Juggler got correct."
			expect(gainedStep(eaten.dies('cannibal'))).toBeUndefined();
		});

		it('not when the Juggler survives the execution, or on a later night', () => {
			// Wiki: "If the Juggler guesses on their first day and dies by execution, tonight the
			// living Cannibal learns how many guesses the Juggler got correct."
			expect(gainedStep(eaten.newDay().dusk())?.gained?.learns).toBeUndefined();
			const lived = guessed
				.do((s) => ({
					type: 'SetOverride',
					seatId: s.seat('juggler'),
					override: { field: 'canDie', value: false }
				}))
				.execute('juggler');
			expect(learns(lived)).toEqual([]);
		});
	});
});
